package com.portfolio.hireflow.interview.controller;import java.time.Instant;import java.util.List;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.portfolio.hireflow.common.response.ApiResponse;import com.portfolio.hireflow.interview.dto.CompanyCalendarEventResponse;import com.portfolio.hireflow.interview.service.CompanyCalendarService;
@RestController @RequestMapping("/api/calendar") @PreAuthorize("hasAnyRole('ADMIN','HR','HIRING_MANAGER','INTERVIEWER')")
public class CompanyCalendarController{private final CompanyCalendarService service;public CompanyCalendarController(CompanyCalendarService service){this.service=service;}@GetMapping public ApiResponse<List<CompanyCalendarEventResponse>> events(@RequestParam Instant from,@RequestParam Instant to,Authentication a){return ApiResponse.ok("已取得公司面試行事曆",service.events(a.getName(),from,to));}}
